void setup() {
  pinMode(10, OUTPUT); // Rueda izquierda
  pinMode(11, OUTPUT); // Rueda derecha
}

void loop() {
  // Rueda Izquierda avanza
  digitalWrite(10, HIGH);
  delayMicroseconds(2000); 
  digitalWrite(10, LOW);

  // Rueda Derecha avanza
  digitalWrite(11, HIGH);
  delayMicroseconds(1000); 
  digitalWrite(11, LOW);

  delay(20); // Pausa de estabilidad
}
